SELECT 
FROM TBL_COMPLIANCE_RESULT
WHERE DELETE_FLAG = 0

    AND RULE_ID = #{ruleId}


    AND REPORT_ID = #{reportId}


    AND CHECK_STATUS = #{checkStatus}


    AND IS_PASSED = #{isPassed}


    AND SEVERITY_LEVEL = #{severityLevel}


    AND COMPANY_ID = #{companyId}

ORDER BY CHECK_TIME DESC

